import{_ as s,a0 as o,w as a,s as p,ao as u,I as l,x as t,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const I=JSON.parse('{"title":"Kubernetes 架构指南 | LCTT x X-CMD","titleTemplate":false,"description":"Kubernetes 架构指南 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Kubernetes 架构指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Kubernetes 架构指南 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220214 A guide to Kubernetes architecture","title":"Kubernetes 架构指南","tag":"202207","desc":""},"relativePath":"202207/20220214 A guide to Kubernetes architecture.md","filePath":"[post].md"}'),d={name:"202207/20220214 A guide to Kubernetes architecture.md"};function b(m,e,f,P,A,T){const r=o("Link");return a(),p("div",null,[e[40]||(e[40]=u('<h1 id="kubernetes-架构指南" tabindex="-1">Kubernetes 架构指南 <a class="header-anchor" href="#kubernetes-架构指南" aria-label="Permalink to “Kubernetes 架构指南”">​</a></h1><blockquote><p>了解 Kubernetes 架构中不同组件是如何组合在一起的，这样你就可以更好地排查问题、维护一个健康的集群，以及优化工作流。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202207/03/105135ey33hhx022m9y9fr.jpg" alt=""></p><p>使用 Kubernetes 来编排容器，这种描述说起来简单，但理解它的实际含义以及如何实现它完全是另外一回事。如果你正在运行或管理 Kubernetes 集群，那么你就会知道 Kubernetes 由一台称为 “<ruby>控制平面<rt>control plane</rt></ruby>” 的机器和许多其他 <ruby>工作节点<rt>worker node</rt></ruby> 机器组成。每种类型都有一个复杂但稳定的堆栈，这使编排成为可能，熟悉每个组件有助于理解它是如何工作的。</p><p><img src="https://opensource.com/sites/default/files/uploads/kubernetes-architecture-diagram.png" alt="Kubernetes 架构图" title="Kubernetes architecture diagram"></p>',5)),l("p",null,[l("em",null,[e[1]||(e[1]=t("（Nived Velayudhan, ",-1)),i(r,{href:"https://creativecommons.org/licenses/by-sa/4.0/"},{default:n(()=>[...e[0]||(e[0]=[t("CC BY-SA 4.0",-1)])]),_:1}),e[2]||(e[2]=t("）",-1))])]),e[41]||(e[41]=u('<h3 id="控制平面组件" tabindex="-1">控制平面组件 <a class="header-anchor" href="#控制平面组件" aria-label="Permalink to “控制平面组件”">​</a></h3><p>Kubernetes 安装在一个称为“<ruby>控制平面<rt>control plane</rt></ruby>”的机器上，它会运行 Kubernetes 守护进程，并在启动容器和<ruby>容器组<rt>pod</rt></ruby>时与之通信。下面介绍控制平面的各个组件。</p><h4 id="etcd" tabindex="-1">etcd <a class="header-anchor" href="#etcd" aria-label="Permalink to “etcd”">​</a></h4><p>etcd 是一种快速、分布式一致性键值存储器，用作 Kubernetes 对象数据的持久存储，如容器组、副本控制器、密钥和服务。etcd 是 Kubernetes 存储集群状态和元数据的唯一地方。唯一与 etcd 直连的组件是 Kubernetes API 服务器。其他所有组件都通过 API 服务器间接的从 etcd 读写数据。</p><p>etcd 还实现了一个监控功能，它提供了一个基于事件的接口，用于异步监控键的更改。一旦你更改了一个键，它的监控者就会收到通知。API 服务器组件严重依赖于此来获得通知，并将 etcd 变更至期望状态。</p><p><em>为什么 etcd 实例的数量应该是奇数？</em></p>',6)),l("p",null,[e[4]||(e[4]=t("你通常会运行三个、五个或七个 etcd 实例实现高可用（HA）环境，但这是为什么呢？因为 etcd 是分布式数据存储，可以水平扩展它，但你需要确保每个实例中的数据是一致的。因此，需要为系统当前状态达成共识，etcd 为此使用 ",-1)),i(r,{href:"https://www.geeksforgeeks.org/raft-consensus-algorithm/"},{default:n(()=>[...e[3]||(e[3]=[t("RAFT 共识算法",-1)])]),_:1}),e[5]||(e[5]=t("。",-1))]),e[42]||(e[42]=l("p",null,"RAFT 算法需要经过选举（或仲裁）集群才能进入下一个状态。如果你只有两个 etcd 实例并且他们其中一个失败的话，那么 etcd 集群无法转换到新的状态，因为不存在过半这个概念。如果你有三个 etcd 实例，一个实例可能会失败，但仍有 2 个实例可用于进行选举。",-1)),e[43]||(e[43]=l("h4",{id:"api-服务器",tabindex:"-1"},[t("API 服务器 "),l("a",{class:"header-anchor",href:"#api-服务器","aria-label":"Permalink to “API 服务器”"},"​")],-1)),e[44]||(e[44]=l("p",null,"API 服务器是 Kubernetes 中唯一直接与 etcd 交互的组件。Kubernetes 中的其他所有组件都必须通过 API 服务器来处理集群状态，包括客户端（kubectl）。API 服务器具有以下功能：",-1)),l("ul",null,[e[12]||(e[12]=l("li",null,"提供在 etcd 中存储对象的一致方式。",-1)),e[13]||(e[13]=l("li",null,"执行验证对象，防止客户端存储配置不正确的对象（如果它们直接写入 etcd 数据存储，可能会发生这种情况）。",-1)),e[14]||(e[14]=l("li",null,"提供 RESTful API 来创建、更新、修改或删除资源。",-1)),l("li",null,[e[7]||(e[7]=t("提供 ",-1)),i(r,{href:"https://stackoverflow.com/questions/52910322/kubernetes-resource-versioning#:~:text=Optimistic%20concurrency%20control%20(sometimes%20referred,updated%2C%20the%20version%20number%20increases."},{default:n(()=>[...e[6]||(e[6]=[t("乐观并发锁",-1)])]),_:1}),e[8]||(e[8]=t("，在发生更新时，其他客户端永远不会有机会重写对象。",-1))]),e[15]||(e[15]=l("li",null,"对客户端发送的请求进行身份验证和授权。它使用插件提取客户端的用户名、ID、所属组，并确定通过身份验证的用户是否可以对请求的资源执行请求的操作。",-1)),l("li",null,[e[10]||(e[10]=t("如果请求试图创建、修改或删除资源，则负责 ",-1)),i(r,{href:"https://kubernetes.io/docs/reference/access-authn-authz/admission-controllers/"},{default:n(()=>[...e[9]||(e[9]=[t("权限控制",-1)])]),_:1}),e[11]||(e[11]=t("。例如，AlwaysPullImages、DefaultStorageClass 和 ResourceQuota。",-1))]),e[16]||(e[16]=l("li",null,"实现了一种监控机制（类似于 etcd），用户客户端监控更改。这允许调度器和控制器管理器等组件以松耦合的方式与 API 服务器交互。",-1))]),e[45]||(e[45]=u('<h4 id="控制器管理器" tabindex="-1">控制器管理器 <a class="header-anchor" href="#控制器管理器" aria-label="Permalink to “控制器管理器”">​</a></h4><p>在 Kubernetes 中，控制器持续监控集群状态，然后根据需要进行或请求更改。每个控制器都尝试将当前集群状态变更至期望状态。控制器至少跟踪一种 Kubernetes 资源类型，这些对象均有一个字段来表示期望的状态。</p><p>控制器示例：</p><ul><li>副本管理器（管理<ruby>副本控制器<rt>ReplicationController</rt></ruby>资源的控制器）</li><li><ruby>副本集<rt>ReplicaSet</rt></ruby>、<ruby>守护进程集<rt>DaemonSet</rt></ruby> 和任务控制器</li><li>部署控制器</li><li>有状态负载控制器</li><li>节点控制器</li><li>服务控制器</li><li>接入点控制器</li><li>命名空间控制器</li><li><ruby>持久卷<rt>PersistentVolume</rt></ruby>控制器</li></ul><p>控制器通过监控机制来获得变更通知。它们监视 API 服务器对资源的变更，对每次更改执行操作，无论是新建对象还是更新或删除现有对象。大多数时候，这些操作包括创建其他资源或更新监控的资源本身。不过，由于使用监控并不能保证控制器不会错过任何事件，它们还会定期执行一系列操作，确保没有错过任何事件。</p>',5)),l("p",null,[e[19]||(e[19]=t("控制器管理器还执行生命周期功能。例如命名空间创建和生命周期、事件垃圾收集、已终止容器组垃圾收集、",-1)),i(r,{href:"https://kubernetes.io/docs/concepts/architecture/garbage-collection/"},{default:n(()=>[...e[17]||(e[17]=[t("级联删除垃圾收集",-1)])]),_:1}),e[20]||(e[20]=t(" 和节点垃圾收集。有关更多信息，参考 ",-1)),i(r,{href:"https://kubernetes.io/docs/concepts/architecture/cloud-controller/"},{default:n(()=>[...e[18]||(e[18]=[t("云控制器管理器",-1)])]),_:1}),e[21]||(e[21]=t("。",-1))]),e[46]||(e[46]=u('<h4 id="调度器" tabindex="-1">调度器 <a class="header-anchor" href="#调度器" aria-label="Permalink to “调度器”">​</a></h4><p>调度器是一个将容器组分配给节点的控制平面进程。它会监视新创建没有分配节点的容器组。调度器会给每个发现的容器组分配运行它的最佳节点。</p><p>满足容器组调度要求的节点称为可调度节点。如果没有合适的节点，那么容器组会一直处于未调度状态，直到调度器可以安置它。一旦找到可调度节点，它就会运行一组函数来对节点进行评分，并选择得分最高的节点，然后它会告诉 API 服务器所选节点的信息。这个过程称为绑定。</p><p>节点的选择分为两步：</p><ol><li>过滤所有节点的列表，获得可以调度容器组的节点列表（例如，PodFitsResources 过滤器检查候选节点是否有足够的可用资源来满足容器组的特定资源请求）。</li><li>对第一步得到的节点列表进行评分和排序，选择最佳节点。如果得分最高的有多个节点，循环过程可确保容器组会均匀地部署在所有节点上。</li></ol><p>调度决策要考虑的因素包括：</p><ul><li>容器组是否请求硬件/软件资源？节点是否报告内存或磁盘压力情况？</li><li>节点是否有与容器组规范中的节点选择器匹配的标签？</li><li>如果容器组请求绑定到特定地主机端口，该端口是否可用？</li><li>容器组是否容忍节点的污点？</li><li>容器组是否指定节点亲和性或反亲和性规则？</li></ul><p>调度器不会指示所选节点运行容器组。调度器所做的就是通过 API 服务器更新容器组定义。然后 API 服务器通过监控机制通知 kubelet 容器组已被调度，然后目标节点上的 kubelet 服务看到容器组被调度到它的节点，它创建并运行容器组。</p><h3 id="工作节点组件" tabindex="-1">工作节点组件 <a class="header-anchor" href="#工作节点组件" aria-label="Permalink to “工作节点组件”">​</a></h3><p>工作节点运行 kubelet 代理，这允许控制平面接纳它们来处理负载。与控制平面类似，工作节点使用几个不同的组件来实现这一点。 以下部分描述了工作节点组件。</p><h4 id="kubelet" tabindex="-1">Kubelet <a class="header-anchor" href="#kubelet" aria-label="Permalink to “Kubelet”">​</a></h4><p>Kubelet 是一个运行在集群中每个节点上的代理，负责在工作节点上运行的所有事情。它确保容器在吊舱中运行。</p><p>kubelet服务的主要功能有：</p><ul><li>通过在 API 服务器中创建节点资源来注册它正在运行的节点。</li><li>持续监控 API 服务器上调度到节点的容器组。</li><li>使用配置的容器运行时启动容器组的容器。</li><li>持续监控正在运行的容器，并将其状态、事件和资源消耗报告给 API 服务器。</li><li>运行容器存活探测，在探测失败时重启容器，当 API 服务器中删除容器组时终止（通知服务器容器组终止的消息）。</li></ul><h4 id="服务代理" tabindex="-1">服务代理 <a class="header-anchor" href="#服务代理" aria-label="Permalink to “服务代理”">​</a></h4><p>服务代理（kube-proxy）在每个节点上运行，确保一个容器组可以与另一个容器组通讯，一个节点可以与另一个节点对话，一个容器可以与另一个容器对话。它负责监视 API 服务器对服务和容器组定义的更改，以保持整个网络配置是最新的。当一项服务得到多个容器组的支持时，代理会在这些容器组之间执行负载平衡。</p><p>kube-proxy 之所以叫代理，是因为它最初实际上是一个代理服务器，用于接受连接并将它们代理到容器组。当前的实现是使用 iptables 规则将数据包重定向到随机选择的后端容器组，而无需通过实际的代理服务器。</p><p>关于它工作原理的高级视图：</p><ul><li>当你创建一个服务时，会立即分配一个虚拟 IP 地址。</li><li>API 服务器会通知在工作节点上运行的 kube-proxy 代理有一个新服务。</li><li>每个 kube-proxy 通过设置 iptables 规则使服务可寻址，确保截获每个服务 IP/端口对，并将目的地址修改为支持服务的一个容器组。</li><li>监控 API 服务器对服务或其端点对象的更改。</li></ul><h4 id="容器运行时" tabindex="-1">容器运行时 <a class="header-anchor" href="#容器运行时" aria-label="Permalink to “容器运行时”">​</a></h4><p>容器运行时有两类：</p><ul><li><strong>较低级别的容器运行时：</strong> 它们主要关注运行中的容器并为容器设置命名空间和<ruby>控制组<rt>cgroup</rt></ruby>。</li><li><strong>更高级别的容器运行时（容器引擎）：</strong> 它们专注于格式、解包、管理、共享镜像以及为开发人员提供 API。</li></ul><p>容器运行时负责：</p><ul><li>如果容器镜像本地不存在，则从镜像仓库中提取。</li><li>将镜像解压到写时复制文件系统，所有容器层叠加创建一个合并的文件系统。</li><li>准备一个容器挂载点。</li><li>设置容器镜像的元数据，如覆盖命令、用户输入的入口命令，并设置 SECCOMP 规则，确保容器按预期运行。</li><li>通知内核将进程、网络和文件系统等隔离分配给容器。</li><li>通知内核分配一些资源限制，如 CPU 或内存限制。</li><li>将系统调用（syscall）传递给内核启动容器。</li><li>确保 SElinux/AppArmor 设置正确。</li></ul><h3 id="协同" tabindex="-1">协同 <a class="header-anchor" href="#协同" aria-label="Permalink to “协同”">​</a></h3>',25)),l("p",null,[e[23]||(e[23]=t("系统级组件协同工作，确保 Kubernetes 集群的每个部分都能实现其目和执行其功能。当你深入编辑 ",-1)),i(r,{href:"https://www.redhat.com/sysadmin/yaml-beginners"},{default:n(()=>[...e[22]||(e[22]=[t("YAML 文件",-1)])]),_:1}),e[24]||(e[24]=t(" 时，有时很难理解请求是如何在集群中通信的。现在你已经了解了各个部分是如何组合在一起的，你可以更好地理解 Kubernetes 内部发生了什么，这有助于诊断问题、维护健康的集群并优化你的工作流。",-1))]),e[47]||(e[47]=l("hr",null,null,-1)),l("p",null,[e[26]||(e[26]=t("via: ",-1)),i(r,{href:"https://opensource.com/article/22/2/kubernetes-architecture"},{default:n(()=>[...e[25]||(e[25]=[t("https://opensource.com/article/22/2/kubernetes-architecture",-1)])]),_:1})]),l("p",null,[e[31]||(e[31]=t("作者：",-1)),i(r,{href:"https://opensource.com/users/nivedv"},{default:n(()=>[...e[27]||(e[27]=[t("Nived Velayudhan",-1)])]),_:1}),e[32]||(e[32]=t(" 选题：",-1)),i(r,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[28]||(e[28]=[t("lujun9972",-1)])]),_:1}),e[33]||(e[33]=t(" 译者：",-1)),i(r,{href:"https://github.com/MjSeven"},{default:n(()=>[...e[29]||(e[29]=[t("MjSeven",-1)])]),_:1}),e[34]||(e[34]=t(" 校对：",-1)),i(r,{href:"https://github.com/turbokernel"},{default:n(()=>[...e[30]||(e[30]=[t("turbokernel",-1)])]),_:1})]),l("p",null,[e[37]||(e[37]=t("本文由 ",-1)),i(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[35]||(e[35]=[t("LCTT",-1)])]),_:1}),e[38]||(e[38]=t(" 原创编译，",-1)),i(r,{href:"https://linux.cn/"},{default:n(()=>[...e[36]||(e[36]=[t("Linux中国",-1)])]),_:1}),e[39]||(e[39]=t(" 荣誉推出",-1))])])}const y=s(d,[["render",b]]);export{I as __pageData,y as default};
